import{_ as a,c as i,o as s,a6 as r}from"./chunks/framework.BY05barL.js";const o="/ucasal-ssoo-estudio/assets/22-maquina-virtual-sistema.CZPNyF3q.png",t="/ucasal-ssoo-estudio/assets/22-maquina-virtual-proceso.d1YoYiW3.png",l="/ucasal-ssoo-estudio/assets/22-hipervisor.BIpKknZv.png",q=JSON.parse('{"title":"Máquinas Virtuales","description":"","frontmatter":{},"headers":[],"relativePath":"unidad1/maquinas-virtuales.md","filePath":"unidad1/maquinas-virtuales.md"}'),n={name:"unidad1/maquinas-virtuales.md"};function u(d,e,p,c,m,h){return s(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="maquinas-virtuales" tabindex="-1">Máquinas Virtuales <a class="header-anchor" href="#maquinas-virtuales" aria-label="Permalink to &quot;Máquinas Virtuales&quot;">​</a></h1><p>Las máquinas virtuales son entornos de ejecución que simulan un sistema de computación completo. Existen dos tipos principales de máquinas virtuales, cada una con propósitos diferentes.</p><h2 id="tipos-de-maquinas-virtuales" tabindex="-1">Tipos de Máquinas Virtuales <a class="header-anchor" href="#tipos-de-maquinas-virtuales" aria-label="Permalink to &quot;Tipos de Máquinas Virtuales&quot;">​</a></h2><h3 id="maquinas-virtuales-de-sistema" tabindex="-1">Máquinas Virtuales de Sistema <a class="header-anchor" href="#maquinas-virtuales-de-sistema" aria-label="Permalink to &quot;Máquinas Virtuales de Sistema&quot;">​</a></h3><ul><li>Dividen un servidor físico en múltiples servidores virtuales</li><li>Cada servidor virtual tiene su propio sistema operativo</li><li>Permiten ejecutar múltiples sistemas operativos en un mismo hardware</li><li>Proporcionan aislamiento entre los diferentes sistemas</li></ul><p><img src="'+o+'" alt="Máquina Virtual de Sistema"></p><h3 id="maquinas-virtuales-de-proceso" tabindex="-1">Máquinas Virtuales de Proceso <a class="header-anchor" href="#maquinas-virtuales-de-proceso" aria-label="Permalink to &quot;Máquinas Virtuales de Proceso&quot;">​</a></h3><ul><li>Se ejecutan como un proceso normal en el sistema operativo</li><li>Sirven de enlace entre un Lenguaje de Programación y el SO</li><li>Realizan una interpretación/transpilación u otra técnica de enlace del Código Fuente a Código Máquina</li><li>Ejemplos: JVM (Java Virtual Machine), CLR (.NET Common Language Runtime)</li></ul><p><img src="'+t+'" alt="Máquina Virtual de Proceso"></p><h2 id="hipervisor" tabindex="-1">Hipervisor <a class="header-anchor" href="#hipervisor" aria-label="Permalink to &quot;Hipervisor&quot;">​</a></h2><p>El hipervisor es un software que permite crear y gestionar máquinas virtuales:</p><ul><li>Es un software que simula una computadora</li><li>Permite ejecutar múltiples sistemas operativos dentro de un mismo sistema físico</li><li>Gestiona los recursos del hardware y los asigna a las máquinas virtuales</li></ul><p><img src="'+l+'" alt="Hipervisor"></p><h2 id="tipos-de-hipervisores" tabindex="-1">Tipos de Hipervisores <a class="header-anchor" href="#tipos-de-hipervisores" aria-label="Permalink to &quot;Tipos de Hipervisores&quot;">​</a></h2><h3 id="hipervisor-tipo-1-bare-metal" tabindex="-1">Hipervisor Tipo 1 (Bare-metal) <a class="header-anchor" href="#hipervisor-tipo-1-bare-metal" aria-label="Permalink to &quot;Hipervisor Tipo 1 (Bare-metal)&quot;">​</a></h3><ul><li>Se ejecuta directamente sobre el hardware</li><li>No requiere un sistema operativo anfitrión</li><li>Más eficiente y seguro</li><li>Ejemplos: VMware ESXi, Microsoft Hyper-V, Xen</li></ul><h3 id="hipervisor-tipo-2-hosted" tabindex="-1">Hipervisor Tipo 2 (Hosted) <a class="header-anchor" href="#hipervisor-tipo-2-hosted" aria-label="Permalink to &quot;Hipervisor Tipo 2 (Hosted)&quot;">​</a></h3><ul><li>Se ejecuta como una aplicación sobre un sistema operativo anfitrión</li><li>Menos eficiente pero más flexible</li><li>Ejemplos: VMware Workstation, Oracle VirtualBox, Parallels Desktop</li></ul><h2 id="ventajas-de-las-maquinas-virtuales" tabindex="-1">Ventajas de las Máquinas Virtuales <a class="header-anchor" href="#ventajas-de-las-maquinas-virtuales" aria-label="Permalink to &quot;Ventajas de las Máquinas Virtuales&quot;">​</a></h2><ul><li><strong>Consolidación de servidores</strong>: Permite ejecutar múltiples servidores en un solo hardware</li><li><strong>Aislamiento</strong>: Cada máquina virtual está aislada de las demás</li><li><strong>Portabilidad</strong>: Las máquinas virtuales pueden moverse fácilmente entre diferentes hosts</li><li><strong>Snapshots</strong>: Permiten guardar el estado de una máquina virtual en un momento dado</li><li><strong>Recuperación ante desastres</strong>: Facilitan la implementación de estrategias de respaldo y recuperación</li></ul><h2 id="aplicaciones" tabindex="-1">Aplicaciones <a class="header-anchor" href="#aplicaciones" aria-label="Permalink to &quot;Aplicaciones&quot;">​</a></h2><ul><li><strong>Desarrollo y pruebas</strong>: Entornos aislados para desarrollo y pruebas</li><li><strong>Consolidación de servidores</strong>: Reducción de costos de hardware y energía</li><li><strong>Computación en la nube</strong>: Base para servicios de infraestructura como servicio (IaaS)</li><li><strong>Seguridad</strong>: Aislamiento de aplicaciones y sistemas</li><li><strong>Educación</strong>: Entornos de aprendizaje seguros y controlados</li></ul>',22)])])}const g=a(n,[["render",u]]);export{q as __pageData,g as default};
